CREATE TABLE article_categories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL,description TEXT NOT NULL DEFAULT '');
CREATE TABLE article_tags(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name TEXT NOT NULL,slug TEXT UNIQUE NOT NULL);
CREATE TABLE articles(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,slug TEXT UNIQUE NOT NULL,title TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','in_review','approved','scheduled','published','archived')),category_id BIGINT REFERENCES article_categories(id),author_id BIGINT NOT NULL REFERENCES users(id),snapshot JSONB NOT NULL,version INTEGER NOT NULL DEFAULT 1,current_revision_id BIGINT,published_revision_id BIGINT,published_at TIMESTAMPTZ,scheduled_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE article_revisions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,article_id BIGINT NOT NULL REFERENCES articles(id),version INTEGER NOT NULL,snapshot JSONB NOT NULL,actor_id BIGINT NOT NULL REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(article_id,version));
ALTER TABLE articles ADD FOREIGN KEY(current_revision_id) REFERENCES article_revisions(id), ADD FOREIGN KEY(published_revision_id) REFERENCES article_revisions(id);
CREATE TABLE article_tag_links(article_id BIGINT REFERENCES articles(id),tag_id BIGINT REFERENCES article_tags(id),PRIMARY KEY(article_id,tag_id));
CREATE TABLE article_product_links(article_id BIGINT REFERENCES articles(id),product_id BIGINT REFERENCES products(id),PRIMARY KEY(article_id,product_id));
CREATE TABLE article_workflow_events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,article_id BIGINT REFERENCES articles(id),from_status TEXT,to_status TEXT NOT NULL,actor_id BIGINT REFERENCES users(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE article_publish_jobs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,article_id BIGINT NOT NULL REFERENCES articles(id),revision_id BIGINT NOT NULL REFERENCES article_revisions(id),due_at TIMESTAMPTZ NOT NULL,state TEXT NOT NULL DEFAULT 'pending' CHECK(state IN ('pending','done','cancelled')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX article_one_pending_job ON article_publish_jobs(article_id) WHERE state='pending';
CREATE INDEX article_due_jobs ON article_publish_jobs(due_at) WHERE state='pending';
CREATE INDEX article_publication ON articles(published_at) WHERE published_revision_id IS NOT NULL;
